@Test
public void testGetDayOfWeek_1990_02_28() {
    LocalDate date = new LocalDate(1990, 2, 28);
    assertArrayEquals(new int[]{6}, new int[]{date.getDayOfWeek()});
}

@Test
public void testGetDayOfWeek_2010_12_31() {
    LocalDate date = new LocalDate(2010, 12, 31);
    assertArrayEquals(new int[]{7}, new int[]{date.getDayOfWeek()});
}

@Test
public void testGetDayOfWeek_1800_01_01() {
    LocalDate date = new LocalDate(1800, 1, 1);
    assertArrayEquals(new int[]{2}, new int[]{date.getDayOfWeek()});
}

@Test
public void testGetDayOfWeek_2100_12_31() {
    LocalDate date = new LocalDate(2100, 12, 31);
    assertArrayEquals(new int[]{1}, new int[]{date.getDayOfWeek()});
}

@Test
public void testGetDayOfWeek_1900_12_31() {
    LocalDate date = new LocalDate(1900, 12, 31);
    assertArrayEquals(new int[]{7}, new int[]{date.getDayOfWeek()});
}

@Test
public void testGetDayOfWeek_1900_01_01_leap() {
    LocalDate date = new LocalDate(1900, 1, 1);
    assertArrayEquals(new int[]{2}, new int[]{date.getDayOfWeek()});
}

@Test
public void testGetDayOfWeek_2000_02_29() {
    LocalDate date = new LocalDate(2000, 2, 29);
    assertArrayEquals(new int[]{4}, new int[]{date.getDayOfWeek()});
}
